const $=s=>document.querySelector(s), app=$('#app');
const categories=['전체','미술·공예','음식·요리','자연·농촌','레저·야외활동','문화·지역탐방','힐링·웰니스'];
const photos={pottery:'https://images.pexels.com/photos/6694323/pexels-photo-6694323.jpeg?auto=compress&w=1000',baking:'https://images.pexels.com/photos/6996298/pexels-photo-6996298.jpeg?auto=compress&w=1000',lake:'https://images.pexels.com/photos/33495169/pexels-photo-33495169/free-photo-of-tranquil-canoe-on-a-misty-lake-edge.jpeg?auto=compress&w=1000'};
const programs=[
{id:'pottery',title:'흙으로 빚는 나만의 도자기',category:'미술·공예',vendor:'춘천 도예공방 · 예시 업체',area:'춘천 시내',price:45000,minutes:90,target:'누구나',place:'실내',image:photos.pottery,tag:'손끝으로 만드는 시간',desc:'흙을 만지고 모양을 빚으며 나만의 작은 그릇을 만들어 보는 체험입니다. 처음 참여하는 분도 기초 설명부터 차근차근 따라갈 수 있습니다.',steps:['도구와 흙의 특성 알아보기 · 15분','그릇 모양 만들기 · 55분','장식과 마무리 · 20분'],prepare:'편한 복장으로 참여하세요. 완성품 수령·배송 방법은 운영 업체와 확인하는 항목입니다.',age:8},
{id:'baking',title:'갓 구운 쿠키, 나의 첫 베이킹',category:'음식·요리',vendor:'춘천 베이킹 스튜디오 · 예시 업체',area:'춘천 시내',price:38000,minutes:120,target:'가족',place:'실내',image:photos.baking,tag:'가족과 함께',desc:'반죽부터 모양 만들기, 굽기까지 직접 해보는 쿠키 체험입니다. 완성된 쿠키를 포장해 가져가는 과정을 경험해 보세요.',steps:['재료 설명과 반죽 · 30분','쿠키 모양 만들기 · 40분','굽기와 포장 · 50분'],prepare:'식품 알레르기가 있다면 예약 전 업체 확인이 필요합니다. 예시 프로그램에는 밀·우유·달걀이 포함됩니다.',age:6},
{id:'canoe',title:'물 위에서 만나는 조용한 춘천',category:'레저·야외활동',vendor:'춘천 수상체험센터 · 예시 업체',area:'춘천 외곽',price:35000,minutes:60,target:'성인',place:'실외',image:photos.lake,tag:'자연 속 한 시간',desc:'기본 안전 교육 후 카누를 타며 물 위의 풍경을 느껴보는 체험입니다. 실제 운영 장소와 기상에 따른 진행 여부는 업체 확정이 필요합니다.',steps:['안전 교육과 장비 착용 · 15분','카누 체험 · 35분','장비 반납과 마무리 · 10분'],prepare:'젖어도 되는 신발과 여벌 옷을 준비하세요. 기상 상황에 따라 업체가 취소할 수 있습니다.',age:18},
{id:'gallery',title:'그림을 읽는 작은 갤러리 산책',category:'문화·지역탐방',vendor:'마인갤러리 · 예시 프로그램',area:'춘천 시내',price:20000,minutes:60,target:'누구나',place:'실내',image:photos.pottery,tag:'작품과 대화하기',desc:'작품을 보는 관점을 나누고 감상을 기록하는 소규모 갤러리 해설 프로그램입니다. 전시와 작품 정보는 실제 운영 시 등록합니다.',steps:['전시 소개 · 10분','작품 감상과 해설 · 35분','감상 나누기 · 15분'],prepare:'편하게 참여할 수 있습니다. 실제 전시 사진과 상세 주소는 업체 등록 후 제공됩니다.',age:8},
{id:'nature',title:'계절을 느끼는 자연 관찰',category:'자연·농촌',vendor:'춘천 생태체험공간 · 예시 업체',area:'춘천 외곽',price:25000,minutes:90,target:'가족',place:'실외',image:photos.lake,tag:'아이와 자연 만나기',desc:'주변의 식물과 풍경을 관찰하며 계절의 변화를 알아보는 가족 체험입니다. 보호자와 어린이가 함께 참여하는 예시 프로그램입니다.',steps:['관찰 방법 소개 · 15분','자연 관찰 활동 · 55분','관찰 기록 나누기 · 20분'],prepare:'걷기 편한 신발, 모자, 개인 물을 준비하세요.',age:6},
{id:'tea',title:'차 한 잔으로 쉬어가는 시간',category:'힐링·웰니스',vendor:'춘천 차문화공간 · 예시 업체',area:'춘천 시내',price:30000,minutes:60,target:'성인',place:'실내',image:photos.baking,tag:'온전히 나를 위한',desc:'차를 우리는 기본 과정을 배우고 향과 맛을 느끼며 쉬어가는 체험입니다. 제공되는 차 종류는 실제 업체 등록 시 확정됩니다.',steps:['차와 도구 소개 · 15분','차 우리기 · 25분','시음과 감상 · 20분'],prepare:'카페인 민감 여부를 확인하세요. 실제 차 종류와 성분은 업체에 문의해야 합니다.',age:18}
];
let filters={q:'',category:'전체',target:'전체',place:'전체',price:'all',duration:'all',date:''}, draft=null, bookings=[], profile={name:'체험 방문자'}, auth=false;
const money=n=>n.toLocaleString('ko-KR')+'원', escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function localDate(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function go(hash){location.hash=hash}function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function card(p){return `<a class="card" href="#experience/${p.id}"><div class="photo"><img src="${p.image}" alt="${p.category} 참고 사진" loading="lazy"><span class="badge">${p.category}</span></div><p class="meta">${p.area} · ${p.minutes}분</p><h3>${p.title}</h3><div class="price">${money(p.price)}<small>/ 1인</small></div><div class="tags"><span>${p.target}</span><span>${p.place}</span><span>예시 체험</span></div></a>`}
function chips(){return `<div class="categories" aria-label="체험 카테고리">${categories.map(c=>`<button class="chip ${filters.category===c?'active':''}" data-category="${c}" aria-pressed="${filters.category===c}">${c}</button>`).join('')}</div>`}
function search(){return `<form class="search-box" id="search"><input aria-label="체험 검색" name="query" placeholder="어떤 체험을 찾으세요?" value="${escape(filters.q)}"><button class="btn" type="submit">검색</button></form>`}
function matches(){return programs.filter(p=>(filters.category==='전체'||p.category===filters.category)&&(!filters.q||[p.title,p.category,p.vendor].join(' ').includes(filters.q))&&(filters.target==='전체'||p.target===filters.target||p.target==='누구나')&&(filters.place==='전체'||p.place===filters.place)&&(filters.price==='all'||p.price<=Number(filters.price))&&(filters.duration==='all'||(filters.duration==='60'?p.minutes<=60:p.minutes>60)))}
function home(){app.innerHTML=`<section class="intro"><div class="intro-text"><span class="eyebrow">MEET CHUNCHEON</span><h1>춘천에서,<br>나의 새로운 경험을 찾다.</h1><p>만들고, 맛보고, 자연을 느끼는 시간.<br>마음에 드는 체험을 골라보세요.</p><a class="btn lime" href="#explore">체험 둘러보기</a></div><img src="${photos.pottery}" alt="손으로 흙을 빚는 도자기 체험 참고 사진"></section><section><div class="section-head"><div><h2>어떤 경험을 해볼까요?</h2><p>개별 체험을 선택하고 원하는 날짜에 참여하세요.</p></div><a class="plain-link" href="#explore">전체 보기</a></div>${chips()}${search()}<div class="grid">${matches().map(card).join('')}</div></section>`;bindSearch()}
function explore(){app.innerHTML=`<h1 class="page-title">체험 찾기</h1>${search()}${chips()}<div class="filters"><label>참여 날짜 <input type="date" id="date-filter" min="${localDate()}" value="${filters.date}"></label><select id="target" aria-label="참여 대상">${['전체','어린이','성인','가족','누구나'].map(v=>`<option ${filters.target===v?'selected':''}>${v}</option>`).join('')}</select><select id="place" aria-label="장소 유형">${['전체','실내','실외'].map(v=>`<option ${filters.place===v?'selected':''} value="${v}">${v==='전체'?'실내·실외':v}</option>`).join('')}</select><select id="price" aria-label="가격"><option value="all">가격 전체</option><option value="30000">3만 원 이하</option><option value="40000">4만 원 이하</option></select><select id="duration" aria-label="소요 시간"><option value="all">소요 시간 전체</option><option value="60">1시간 이하</option><option value="long">1~2시간</option></select><button class="text-btn" id="reset">초기화</button></div><p class="count">총 ${matches().length}개의 체험 · ${filters.date?escape(filters.date)+' 예시 일정':'예시 프로그램'}</p>${matches().length?`<div class="grid">${matches().map(card).join('')}</div>`:`<div class="empty"><h2>조건에 맞는 체험이 없습니다.</h2><p>검색어나 필터를 변경해 보세요.</p><button class="btn" id="empty-reset">필터 초기화</button></div>`}`;bindSearch();['target','place','price','duration'].forEach(key=>{$('#'+key).value=filters[key];$('#'+key).onchange=e=>{filters[key]=e.target.value;explore()}});$('#date-filter').onchange=e=>{filters.date=e.target.value;explore()};$('#reset').onclick=reset;const e=$('#empty-reset');if(e)e.onclick=reset}
function reset(){filters={q:'',category:'전체',target:'전체',place:'전체',price:'all',duration:'all',date:''};explore()}
function bindSearch(){document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{filters.category=b.dataset.category;if(location.hash==='#explore')explore();else go('explore')});$('#search').onsubmit=e=>{e.preventDefault();filters.q=e.target.query.value.trim();if(location.hash==='#explore')explore();else go('explore')}}
function detail(id){const p=programs.find(p=>p.id===id);if(!p)return missing();app.innerHTML=`<p class="breadcrumb"><a href="#explore">체험 찾기</a> / ${p.category}</p><img class="detail-cover" src="${p.image}" alt="${p.category} 체험 참고 사진"><div class="detail-layout"><article><span class="eyebrow" style="color:#668034">${p.category}</span><h1>${p.title}</h1><p class="policy-note">${p.vendor}</p><div class="summary"><span>${p.minutes}분</span><span>${p.place}</span><span>만 ${p.age}세 이상</span><span>최대 8명 · 예시 정원</span></div><section class="body-section"><h2>체험 소개</h2><p>${p.desc}</p></section><section class="body-section"><h2>진행 순서</h2><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol></section><section class="body-section"><h2>준비물·참여 안내</h2><p>${p.prepare}</p></section><section class="body-section"><h2>체험 장소</h2><p>${p.area} · 상세 주소는 실제 업체 등록 후 제공됩니다.</p></section><section class="body-section"><h2>취소·환불 안내</h2><p>시제품 정책: 체험일 3일 전까지 100%, 1~2일 전 50%, 당일 0%. 업체 취소 시 100%. 실제 운영 정책은 출시 전에 확정합니다.</p></section><p class="policy-note">사진은 참고 이미지로 실제 업체·장소와 다릅니다. <a class="plain-link" href="#policy">사진 출처</a></p></article><form class="panel booking-panel" id="reserve"><span class="policy-note">1인 체험 비용</span><p class="price">${money(p.price)}</p><div class="form-row"><label for="date">참여 날짜</label><input type="date" id="date" required min="${localDate()}" value="${filters.date||localDate(3)}"></div><div class="form-row"><label for="time">참여 시간</label><select id="time"><option>10:00</option><option>14:00</option><option>16:00</option></select></div><div class="form-row"><label for="people">참여 인원</label><select id="people">${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}">${n}명</option>`).join('')}</select></div><div class="total"><span>총 체험 비용</span><span id="total">${money(p.price)}</span></div><button class="btn wide" type="submit">예약 정보 입력</button><p class="policy-note">일정·잔여 정원은 예시입니다. 실제 예약은 접수되지 않습니다.</p></form></div>`;$('#people').onchange=e=>$('#total').textContent=money(p.price*Number(e.target.value));$('#reserve').onsubmit=e=>{e.preventDefault();if($('#date').value<localDate())return toast('오늘 이후 날짜를 선택하세요.');draft={programId:p.id,date:$('#date').value,time:$('#time').value,people:Number($('#people').value)};go('checkout')}}
function checkout(){if(!draft)return go('explore');const p=programs.find(p=>p.id===draft.programId);app.innerHTML=`<p class="breadcrumb"><a href="#experience/${p.id}">체험 상세</a> / 예약 정보</p><h1 class="page-title">예약 정보 확인</h1><form id="checkout" class="checkout"><section><div class="panel"><h2>선택한 체험</h2><div class="mini"><img src="${p.image}" alt="체험 참고 사진"><div><h3>${p.title}</h3><p>${draft.date} ${draft.time} · ${draft.people}명</p></div></div></div><div class="panel" style="margin-top:20px"><h2>예약자 정보</h2><div class="form-row"><label for="name">예약자 이름</label><input id="name" maxlength="30" value="체험 방문자" required autocomplete="off"></div><p class="policy-note">테스트용 이름만 입력해 주세요. 시제품에서는 연락처와 결제정보를 수집하지 않습니다.</p></div><div class="notice">현재는 예약 흐름을 확인하는 단계입니다. PG 결제창, 실시간 정원 확인, 업체 통보와 계좌 지급은 연결되지 않았습니다.</div></section><aside class="panel booking-panel"><h2>결제 금액</h2><p>${money(p.price)} × ${draft.people}명</p><div class="total"><span>총 결제 금액</span><span>${money(p.price*draft.people)}</span></div><label class="check"><input type="checkbox" required><span>예시 취소 규정과 실제 결제가 발생하지 않는다는 점을 확인했습니다.</span></label><button class="btn wide" type="submit">결제 없이 예약 흐름 체험</button><p class="policy-note">실제 운영에서는 이 단계에서 PG 결제로 연결됩니다.</p></aside></form>`;$('#checkout').onsubmit=e=>{e.preventDefault();const b={...draft,id:'DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase(),name:$('#name').value.trim(),status:'confirmed',total:p.price*draft.people};if(!b.name)return toast('테스트 이름을 입력해 주세요.');bookings.unshift(b);draft=null;go('result/'+b.id)}}
function result(id){const b=bookings.find(b=>b.id===id);if(!b)return missing();app.innerHTML=`<div class="narrow" style="text-align:center"><div class="success-symbol">✓</div><h1 class="page-title">예시 예약이 만들어졌습니다.</h1><p>실제 결제·예약·업체 통보는 발생하지 않았습니다.<br>내 예약에서 예약 상세와 취소 흐름을 확인할 수 있습니다.</p><div class="ticket"><span>예시 예약번호</span><strong>${b.id}</strong><span>${b.date} ${b.time} · ${b.people}명</span></div><div class="button-row" style="justify-content:center"><a class="btn" href="#booking/${b.id}">예약 상세 보기</a><a class="btn secondary" href="#explore">다른 체험 보기</a></div></div>`}
function listBookings(){app.innerHTML=`<h1 class="page-title">내 예약</h1><div class="notice">이 브라우저에서 만든 예시 예약입니다. 새로고침하면 초기화됩니다.</div>${bookings.length?bookings.map(b=>{const p=programs.find(p=>p.id===b.programId);return `<article class="reservation"><img src="${p.image}" alt="체험 참고 사진"><div class="grow"><span class="status ${b.status==='cancelled'?'cancelled':''}">${b.status==='cancelled'?'예시 취소 완료':'예시 예약'}</span><h3>${p.title}</h3><p>${b.date} ${b.time} · ${b.people}명 · ${money(b.total)}</p></div><a class="btn secondary" href="#booking/${b.id}">상세 보기</a></article>`}).join(''):`<div class="empty"><h2>아직 예약한 체험이 없습니다.</h2><p>마음에 드는 체험을 찾아 예약 흐름을 확인해 보세요.</p><a class="btn" href="#explore">체험 찾아보기</a></div>`}`}
function booking(id){const b=bookings.find(b=>b.id===id);if(!b)return missing();const p=programs.find(p=>p.id===b.programId);app.innerHTML=`<div class="narrow"><p class="breadcrumb"><a href="#bookings">내 예약</a> / 예약 상세</p><h1 class="page-title">예약 상세</h1><div class="panel"><span class="status ${b.status==='cancelled'?'cancelled':''}">${b.status==='cancelled'?'예시 취소 완료':'예시 예약'}</span><div class="mini"><img src="${p.image}" alt="체험 참고 사진"><div><h3>${p.title}</h3><p>${p.vendor}</p></div></div><div class="total"><span>참여 일정</span><span>${b.date} ${b.time}</span></div><div class="total"><span>인원·예약자</span><span>${b.people}명 · ${escape(b.name)}</span></div><div class="total"><span>예시 결제 금액</span><span>${money(b.total)}</span></div>${b.status==='cancelled'?`<div class="notice">예시 환불액: ${money(b.refund)} · 실제 환불은 발생하지 않았습니다.</div>`:`<div class="ticket"><span>체험 당일 보여줄 예약번호</span><strong>${b.id}</strong><span>유효한 이용권이 아닌 시제품 화면입니다.</span></div>`}<h3>찾아가는 길</h3><p class="policy-note">${p.area} · 상세 주소는 실제 업체 등록 후 안내됩니다.</p></div><div class="button-row">${b.status!=='cancelled'?`<a class="btn secondary" href="#cancel/${b.id}">예약 취소</a>`:''}<a class="btn secondary" href="#bookings">목록으로</a></div></div>`}
function cancel(id){const b=bookings.find(b=>b.id===id);if(!b||b.status==='cancelled')return go('bookings');const days=Math.round((new Date(b.date+'T00:00:00')-new Date(localDate()+'T00:00:00'))/86400000),rate=days>=3?1:days>=1?.5:0;app.innerHTML=`<div class="narrow"><h1 class="page-title">예약 취소 확인</h1><form id="cancel-form" class="panel"><h3>${programs.find(p=>p.id===b.programId).title}</h3><p>${b.date} ${b.time} · ${b.people}명</p><div class="total"><span>예시 결제 금액</span><span>${money(b.total)}</span></div><div class="total"><span>예시 환불액 (${rate*100}%)</span><span>${money(b.total*rate)}</span></div><p class="policy-note">시제품 취소 규정에 따른 계산입니다. 실제 결제 내역과 환불은 없습니다.</p><div class="form-row"><label for="reason">취소 사유</label><select id="reason"><option>일정 변경</option><option>다른 체험 선택</option><option>기타</option></select></div><label class="check"><input type="checkbox" required><span>예시 환불액을 확인했으며 예약 취소를 진행합니다.</span></label><div class="button-row"><button class="btn" type="submit">예시 예약 취소</button><a class="btn secondary" href="#booking/${b.id}">예약 유지</a></div></form></div>`;$('#cancel-form').onsubmit=e=>{e.preventDefault();b.status='cancelled';b.refund=b.total*rate;toast('예시 예약이 취소되었습니다.');go('booking/'+b.id)}}
function profilePage(){app.innerHTML=`<div class="narrow"><h1 class="page-title">마이페이지</h1><div class="panel"><h2>${auth?escape(profile.name)+'님':'방문자 모드'}</h2><p class="policy-note">로그인·회원가입은 화면 확인용입니다. 실제 계정은 생성되지 않습니다.</p><div class="button-row">${auth?'<button class="btn secondary" id="logout">체험 모드 종료</button>':'<a class="btn" href="#login">로그인 화면</a><a class="btn secondary" href="#signup">회원가입 화면</a>'}<a class="btn secondary" href="#bookings">내 예약 보기</a></div></div><div class="body-section"><a href="#help">이용 안내·문의</a></div><div class="body-section"><a href="#policy">약관·개인정보 안내</a></div></div>`;if(auth)$('#logout').onclick=()=>{auth=false;profilePage();toast('체험 모드를 종료했습니다.')}}
function account(mode){const signup=mode==='signup';app.innerHTML=`<div class="narrow"><h1 class="page-title">${signup?'회원가입':'로그인'}</h1><form class="panel" id="account"><h2>계정 화면 체험</h2><p class="policy-note">실제 계정이나 비밀번호를 입력하지 마세요. 별도의 인증 서버 연결 전이며 이름만으로 화면을 확인합니다.</p><div class="form-row"><label for="display-name">테스트 이름</label><input id="display-name" required maxlength="30" placeholder="예: 춘천 방문자"></div><label class="check"><input type="checkbox" required><span>실제 계정이 생성되지 않는 시제품임을 확인했습니다.</span></label><button class="btn" type="submit">${signup?'회원가입 화면 체험':'로그인 화면 체험'}</button><div class="button-row"><a class="plain-link" href="#${signup?'login':'signup'}">${signup?'로그인 화면으로':'회원가입 화면으로'}</a><a class="plain-link" href="#recover">계정 찾기 안내</a></div></form></div>`;$('#account').onsubmit=e=>{e.preventDefault();const name=$('#display-name').value.trim();if(!name)return toast('테스트 이름을 입력해 주세요.');profile.name=name;auth=true;go('profile')}}
function help(){app.innerHTML=`<div class="narrow"><h1 class="page-title">이용 안내·문의</h1><details open><summary>체험은 어떻게 예약하나요?</summary><p>체험 찾기 → 체험 상세 → 날짜·인원 선택 → 예약 정보 확인 순서로 진행합니다. 현재는 예시 예약만 생성됩니다.</p></details><details><summary>실제로 결제되나요?</summary><p>아니요. PG 결제는 연결되지 않았으며 결제정보도 입력받지 않습니다.</p></details><details><summary>예약을 취소하려면 어떻게 하나요?</summary><p>내 예약에서 예약 상세를 열고 예약 취소를 선택하세요. 예시 취소 정책에 따른 환불액을 확인할 수 있습니다.</p></details><details><summary>예약 내역이 사라졌어요.</summary><p>시제품의 예약은 현재 페이지 메모리에만 보관됩니다. 새로고침하거나 창을 닫으면 초기화됩니다.</p></details><details><summary>어린이도 참여할 수 있나요?</summary><p>체험 상세에서 참여 가능 연령과 준비물을 확인하세요. 실제 운영 시 보호자 동반 조건도 상품별로 안내합니다.</p></details><div class="notice">운영 문의 연락처는 마인갤러리의 실제 연락처 확인 후 등록할 예정입니다.</div></div>`}
function policy(){app.innerHTML=`<div class="narrow"><h1 class="page-title">약관·개인정보 안내</h1><div class="notice">운영 약관이 아닌 시제품 안내입니다. 실제 출시 전에 사업자 정보, 서비스 약관, 개인정보 처리방침과 환불 기준을 확정해야 합니다.</div><section class="body-section"><h2>시제품 이용 범위</h2><p>프로그램, 업체, 가격, 일정은 화면 확인용 예시입니다. 실제 체험 예약, 결제, 지급, 업체 통보는 수행하지 않습니다.</p><h2>정보 처리</h2><p>테스트 이름과 예시 예약 정보는 열린 페이지의 메모리에서만 사용합니다. 서버나 브라우저 저장소에 저장하지 않으며 새로고침 시 삭제됩니다. 외부 사진과 글꼴을 불러오는 과정에서 해당 제공자에게 일반적인 접속 정보가 전달될 수 있습니다.</p><h2>예시 취소 규정</h2><p>체험일 3일 전까지 100%, 1~2일 전 50%, 당일 0%의 환불액을 계산합니다. 실제 서비스 정책으로 확정된 내용은 아닙니다.</p><h2>사진 출처</h2><p>모든 사진은 실제 춘천 업체·장소를 나타내지 않는 참고 사진입니다.</p><p><a class="plain-link" href="https://www.pexels.com/photo/a-person-doing-pottery-6694323/" target="_blank" rel="noopener">도자기 · cottonbro studio / Pexels</a><br><a class="plain-link" href="https://www.pexels.com/photo/a-person-holding-a-rolling-pin-on-a-dough-6996298/" target="_blank" rel="noopener">베이킹 · Pavel Danilyuk / Pexels</a><br><a class="plain-link" href="https://www.pexels.com/photo/tranquil-canoe-on-a-misty-lake-edge-33495169/" target="_blank" rel="noopener">카누 · Pexels</a></p></section></div>`}
function missing(){app.innerHTML='<div class="empty"><h1 class="page-title">정보를 찾을 수 없습니다.</h1><p>예시 예약은 페이지를 새로고침하면 초기화됩니다.</p><a class="btn" href="#explore">체험 찾기로 이동</a></div>'}
function render(){const [route='home',id]=location.hash.slice(1).split('/');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#booking-count').textContent=bookings.filter(b=>b.status==='confirmed').length||'';({home,explore,experience:()=>detail(id),checkout,result:()=>result(id),bookings:listBookings,booking:()=>booking(id),cancel:()=>cancel(id),profile:profilePage,login:()=>account('login'),signup:()=>account('signup'),help,policy,recover:()=>{app.innerHTML='<div class="narrow"><h1 class="page-title">계정 찾기</h1><div class="notice">실제 계정이 생성되지 않는 시제품입니다. 계정 복구 기능은 인증 서비스 연결 후 제공됩니다.</div><a class="btn" href="#login">로그인 화면으로</a></div>'}}[route]||missing)();window.scrollTo(0,0);document.title=(route==='experience'?programs.find(p=>p.id===id)?.title+' | ':'')+'마인갤러리 · 춘천 체험'}
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_experiences',description:'체험 검색 조건을 적용하고 목록을 표시합니다. 예약은 생성하지 않습니다.',inputSchema:{type:'object',properties:{query:{type:'string'},category:{type:'string',enum:categories}},additionalProperties:false},annotations:{readOnlyHint:false},execute:async(input)=>{if(!input||typeof input!=='object'||(input.query!==undefined&&typeof input.query!=='string')||(input.category!==undefined&&!categories.includes(input.category)))throw new Error('검색 조건이 올바르지 않습니다.');filters.q=input.query||'';filters.category=input.category||'전체';location.hash='explore';explore();return {results:matches().map(p=>({id:p.id,title:p.title,price:p.price}))}}}).catch?.(()=>{});}catch{}}
